(() => {
  'use strict';
  const KEY='snu-lab-favorites-v2';
  const read=()=>{try{const v=JSON.parse(localStorage.getItem(KEY)||'[]');return new Set(Array.isArray(v)?v:[]);}catch(_){return new Set();}};
  const write=s=>localStorage.setItem(KEY,JSON.stringify([...s]));
  function unitIdForRow(row){const name=(row.querySelector('th')?.textContent||'').trim();const lab=(row.children[1]?.textContent||'').trim();const units=[...(window.RESEARCH_UNITS||[]),...(window.RESEARCH_UNIT_SUPPLEMENTS||[])];const matches=units.filter(x=>String(x.name||'').trim()===name);return (matches.find(x=>String(x.labs||x.title||'연구그룹').trim()===lab)||matches[0])?.id||'';}
  async function remove(id,row){if(!id)return;const fav=read();fav.delete(id);write(fav);try{if(window.SnuAccount?.isLoggedIn?.()&&window.SnuAccount?.setFavorite)await window.SnuAccount.setFavorite(id,false);}catch(_){}row.remove();const count=document.querySelector('#favCount');if(count)count.textContent=`${fav.size}개`;const body=document.querySelector('#favDialog tbody');if(body&&!body.children.length){document.querySelector('#favDialog .stable-scroll')?.remove();document.querySelector('#favDialog h2')?.insertAdjacentHTML('afterend','<p>저장된 연구실이 없습니다.</p>');}document.dispatchEvent(new Event('snu-favorites-changed'));}
  function decorate(){const d=document.querySelector('#favDialog');if(!d?.open)return;const table=d.querySelector('table');if(!table)return;const h=table.querySelector('thead tr');if(h&&!h.querySelector('.fav-remove-head')){const th=document.createElement('th');th.className='fav-remove-head';th.textContent='관리';h.appendChild(th);}table.querySelectorAll('tbody tr').forEach(row=>{if(row.querySelector('.fav-remove-cell'))return;const td=document.createElement('td');td.className='fav-remove-cell';const b=document.createElement('button');b.type='button';b.className='fav-remove-direct';b.textContent='즐겨찾기 해제';b.onclick=e=>{e.preventDefault();e.stopPropagation();remove(unitIdForRow(row),row);};td.appendChild(b);row.appendChild(td);});}
  const style=document.createElement('style');style.textContent='.fav-remove-direct{white-space:nowrap;border:1px solid #cbd8e6;background:#fff;color:#135fbe;border-radius:8px;padding:6px 9px;font-weight:700;cursor:pointer}.fav-remove-direct:hover{background:#f3f7fc}';document.head.appendChild(style);
  document.addEventListener('click',e=>{if(e.target.closest?.('#favShow')){setTimeout(decorate,0);setTimeout(decorate,100);setTimeout(decorate,300);}},true);
  new MutationObserver(()=>requestAnimationFrame(decorate)).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['open']});
})();
